from pathlib import Path
import json,hashlib,shutil
r=Path.cwd();dc=r/'docs/coop/design-corrections';author=dc/'reviews/digest-corrections-author.v9';sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();h=json.loads((author/'handoff.json').read_text());a=h['normativeClarificationAssessment']['finalAgreedBytes'];assert a['readInFull'] and a['sha256']=='32db349536ffc74081b5081aa698f9966d100485268fc24822fde2a1a94cd13f';assert json.loads((author/'response.json').read_text())['is_error'] is False
body=author/a['file'];assert sha(body)==a['sha256'] and body.stat().st_size==a['bytes']
rel='docs/v2/contracts/product-v1/identity-and-evidence.md';p=r/rel;m=json.loads((dc/'reviews/candidate-subject.v10.json').read_text());old=next(x for x in m['files'] if x['path']==rel);assert sha(p)==old['sha256'];text=p.read_text();needle='`x-opensip-relation-registry` carries a normative per-relation **`snapshotJoins`**\n';assert text.count(needle)==1
out=dc/'reviews/codex-post-reset.v1/normative-annotation-clarification.v11';assert not out.exists();out.mkdir();shutil.copyfile(p,out/'before.md');shutil.copyfile(body,out/'agreed-insert.md');p.write_text(text.replace(needle,body.read_text().rstrip()+'\n\n'+needle));shutil.copyfile(p,out/'after.md');shutil.copyfile(__file__,out/'apply.py')
(out/'custody.json').write_text(json.dumps({'standing':'Codex applies exact normative insertion substantively assessed by actual Claude coauthor, pending fresh independent successor review and blind reconstruction. Not independent acceptance.','path':rel,'beforeSha256':old['sha256'],'afterSha256':sha(p),'agreedInsert':{'path':str(body.relative_to(r)),'sha256':sha(body),'bytes':body.stat().st_size},'actualClaudeAssessment':{'path':str((author/'handoff.json').relative_to(r)),'sha256':sha(author/'handoff.json'),'selector':'/normativeClarificationAssessment/finalAgreedBytes'},'sourceModelSha256':h['ownedFilesChanged'][0]['sha256'],'registeredSchemaBytesChanged':False,'implementationAuthorized':False},indent=2)+'\n')
print('Applied exact2825-byte mutually assessed normative insert; full before/after retained.')
